// Regenerates lib/src/rich_text/detection/iana_top_level_domains.dart, the
// top-level domains a scheme-less host may end in (EntityDetection).
//
//   dart run tool/generate_tlds.dart [path/to/tlds-alpha-by-domain.txt]
//
// The input is IANA's plain-text root zone list, one domain per line after a
// `# Version <n>, Last Updated <date>` line:
//
//   https://data.iana.org/TLD/tlds-alpha-by-domain.txt
//
// Without an argument the script downloads it. The committed output was made
// from version 2026101700 (last updated Sat Oct 17 07:07:01 2026 UTC), which
// the generated file's header repeats; rerun the script to refresh, then
// review the diff. The script writes only that one file and never executes
// what it downloads.
//
// Internationalised domains (`xn--...`) are left out on purpose: the detector
// accepts every punycode top-level domain by shape, as Telegram Android does,
// so listing them would only be a second source of truth that goes stale.
import 'dart:convert';
import 'dart:io';

const String _sourceUrl = 'https://data.iana.org/TLD/tlds-alpha-by-domain.txt';

Future<void> main(List<String> args) async {
  if (args.length > 1) {
    stderr.writeln('usage: dart run tool/generate_tlds.dart [input-file]');
    exitCode = 64;
    return;
  }
  final source = args.isEmpty
      ? await _download()
      : await File(args.single).readAsString();
  final output = File.fromUri(
    Platform.script.resolve(
      '../lib/src/rich_text/detection/iana_top_level_domains.dart',
    ),
  );
  await output.writeAsString(generate(source));
  final format = await Process.run(Platform.resolvedExecutable, [
    'format',
    output.path,
  ]);
  if (format.exitCode != 0) {
    stderr.write(format.stderr);
    exitCode = format.exitCode;
    return;
  }
  stdout.writeln('Wrote ${output.path}.');
}

Future<String> _download() async {
  final client = HttpClient();
  try {
    final request = await client.getUrl(Uri.parse(_sourceUrl));
    final response = await request.close();
    if (response.statusCode != HttpStatus.ok) {
      throw HttpException('HTTP ${response.statusCode}', uri: request.uri);
    }
    // Strict UTF-8: a list that is not text must fail, not be mangled.
    return await utf8.decodeStream(response);
  } finally {
    client.close();
  }
}

/// The Dart source for the IANA list [source].
String generate(String source) {
  final lines = const LineSplitter().convert(source);
  final version = lines.firstWhere(
    (line) => line.startsWith('# Version '),
    orElse: () => throw const FormatException('No "# Version" line.'),
  );
  final names = <String>{
    for (final line in lines)
      if (line.trim().isNotEmpty && !line.startsWith('#'))
        if (!line.trim().toLowerCase().startsWith('xn--'))
          line.trim().toLowerCase(),
  };
  if (names.length < 500) {
    throw FormatException('Only ${names.length} domains: wrong input?');
  }
  for (final name in names) {
    if (!RegExp(r'^[a-z]{2,63}$').hasMatch(name)) {
      throw FormatException('Not an ASCII top-level domain: $name');
    }
  }
  final sorted = names.toList()..sort();
  final body = [for (final name in sorted) "    '$name',"].join('\n');
  return '''
// GENERATED by tool/generate_tlds.dart. Do not edit; rerun the script.
//
// Source: $_sourceUrl
// IANA: ${version.substring(2)}
//
// Lowercase ASCII top-level domains only; internationalised ones are matched
// by their `xn--` shape (see EntityDetection).

/// The IANA root zone's ASCII top-level domains, the endings a scheme-less
/// host is accepted with.
abstract final class IanaTopLevelDomains {
  /// Whether [label] is a top-level domain on the list, ignoring case.
  static bool contains(String label) => _names.contains(label.toLowerCase());

  static const Set<String> _names = {
$body
  };
}
''';
}
